import React, { useState } from 'react';

const Carousel3D = ({ movies = [] }) => {
  const [currentIndex, setCurrentIndex] = useState(2);

  const displayMovies = movies.length > 0 ? movies : [
    { id: 0, title: "Dune 2", poster_path: "/placeholder1.jpg" },
    { id: 1, title: "Wicked", poster_path: "/placeholder2.jpg" },
    { id: 2, title: "Interstellar", poster_path: "/placeholder3.jpg" },
    { id: 3, title: "Avatar", poster_path: "/placeholder4.jpg" },
    { id: 4, title: "Joker", poster_path: "/placeholder5.jpg" },
  ];

  const total = displayMovies.length;

  const handleNext = () => setCurrentIndex((prev) => (prev + 1) % total);
  const handlePrev = () => setCurrentIndex((prev) => (prev - 1 + total) % total);

  return (
    <div className="relative w-full py-12 flex flex-col items-center justify-center overflow-hidden bg-[#0b090e]">
      
      {/* 💡 3D 스테이지 중앙 정렬 및 perspective 설정 보완 */}
      <div 
        className="relative w-full max-w-5xl h-[400px] flex items-center justify-center" 
        style={{ perspective: '1400px', transformStyle: 'preserve-3d' }}
      >
        {displayMovies.map((movie, index) => {
          let offset = (index - currentIndex + total) % total;
          if (offset > total / 2) offset -= total;

          const translateX = offset * 200;
          const translateZ = -Math.abs(offset) * 80;
          const rotateY = offset * -18;
          const scale = Math.max(1 - Math.abs(offset) * 0.1, 0.75);
          const opacity = Math.abs(offset) > 2.5 ? 0 : 1;

          return (
            <div
              key={movie.id || index}
              onClick={() => setCurrentIndex(index)}
              style={{
                transform: `translate(-50%, -50%) translateX(${translateX}px) translateZ(${translateZ}px) rotateY(${rotateY}deg) scale(${scale})`,
                zIndex: total - Math.abs(offset),
                opacity: opacity,
                pointerEvents: opacity === 0 ? 'none' : 'auto',
                transition: 'all 0.6s cubic-bezier(0.25, 1, 0.5, 1)',
              }}
              className={`absolute left-1/2 top-1/2 w-48 h-72 rounded-xl overflow-hidden cursor-pointer shadow-2xl border bg-zinc-900 ${
                offset === 0 ? 'border-purple-500 shadow-[0_0_25px_rgba(168,85,247,0.3)]' : 'border-white/10 brightness-75'
              }`}
            >
              {movie.poster_path && movie.poster_path.startsWith('/') ? (
                <img src={`https://image.tmdb.org/t/p/w500${movie.poster_path}`} alt={movie.title} className="w-full h-full object-cover pointer-events-none" />
              ) : (
                <div className="w-full h-full bg-zinc-800 flex items-center justify-center text-xs text-zinc-400 p-2 text-center">
                  {movie.title || 'Movie Poster'}
                </div>
              )}
            </div>
          );
        })}
      </div>

      {/* 컨트롤 버튼 */}
      <div className="flex items-center gap-4 mt-6 z-20">
        <button onClick={handlePrev} className="w-9 h-9 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer">&larr;</button>
        <button onClick={handleNext} className="w-9 h-9 rounded-full bg-white/10 text-white flex items-center justify-center hover:bg-white/20 transition cursor-pointer">&rarr;</button>
      </div>

    </div>
  );
};

export default Carousel3D;
